BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(16);
SELECT ok(to_regclass('app_private.admission_application_policy_snapshots') IS NOT NULL,'P44 storage retained');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_binding_snapshot_revision_identity' AND contype='u'),'revision identity key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_binding_predecessor_shape' AND contype='c'),'revision shape');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_binding_exact_predecessor' AND contype='f'),'exact predecessor FK');
SELECT ok((SELECT cardinality(conkey)=3 FROM pg_constraint WHERE conname='db03_binding_exact_predecessor'),'predecessor FK includes three fields');
SELECT ok((SELECT confupdtype='r' AND confdeltype='r' FROM pg_constraint WHERE conname='db03_binding_exact_predecessor'),'predecessor immutable');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_binding_unique_forward_per_application' AND contype='u'),'no duplicate Forward binding');
SELECT ok((SELECT cardinality(conkey)=2 FROM pg_constraint WHERE conname='db03_binding_unique_forward_per_application'),'Forward uniqueness scoped to application');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_mutation_disabled' AND tgenabled='O'),'P44 mutation denied');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.admission_application_policy_snapshots'::regclass),'forced RLS');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_application_policy_snapshots','INSERT'),'client cannot insert');
SELECT ok(NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_application_policy_snapshots','INSERT'),'workflow cannot insert');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_forward'),'P46B-1 Forward retained');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_intake_policy'),'P46B-1 Intake retained');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_unsubmitted_policy_null'),'draft application policy null fence retained');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_application_policy_snapshots),'no policy bindings installed');
SELECT * FROM finish();
ROLLBACK;
